// Prints the room art for src/rooms.ts, and src/rooms.json for scripts/tour.mjs.
//   node scripts/make-rooms.mjs            the art, to paste into src/rooms.ts
//   node scripts/make-rooms.mjs --json     the same art, written to src/rooms.json
//
// The rooms are the 1984 original's: a brick structure with corridors carved out of it, a ladder in a hole in
// each floor, one or two things worth picking up and a creature or two. This file holds the art so every row is
// exactly 20 tiles, which is what src/rooms.ts is checked against by scripts/check-rooms.mjs.
import fs from 'node:fs';

const COLS = 20;
const ROWS = 16;

/**
 * Three storeys of brick with corridors four tiles high. That height matters: Joe is 46 px (1.4 tiles) and his
 * jump is 82 px, so a shorter corridor puts the brick floor through his head and he cannot jump at all.
 *
 *   0        the ceiling
 *   1-4      the top corridor, its floor is row 5
 *   5        the top floor
 *   6-9      the middle corridor, its floor is row 10

display.text:
// Prints the room art for src/rooms.ts, and src/rooms.json for scripts/tour.mjs.
//   node scripts/make-rooms.mjs            the art, to paste into src/rooms.ts
//   node scripts/make-rooms.mjs --json     the same art, written to src/rooms.json
//
// The rooms are the 1984 original's: a brick structure with corridors carved out of it, a ladder in a hole in
// each floor, one or two things worth picking up and a creature or two. This file holds the art so every row is
// exactly 20 tiles, which is what src/rooms.ts is checked against by scripts/check-rooms.mjs.
import fs from 'node:fs';

const COLS = 20;
const ROWS = 16;

/**
 * Three storeys of brick with corridors four tiles high. That height matters: Joe is 46 px (1.4 tiles) and his
 * jump is 82 px, so a shorter corridor puts the brick floor through his head and he cannot jump at all.
 *
 *   0        the ceiling
 *   1-4      the top corridor, its floor is row 5
 *   5        the top floor
 *   6-9      the middle corridor, its floor is row 10
 *   10       the middle floor
 *   11-14    the ground, on the border at row 15
 */
const CEILING = 0;
const TOP = 1;
const TOP_FLOOR = 5;
const MID = 6;
const MID_FLOOR = 10;
const GROUND = 11;
const FLOOR = 15;

const blank = () => Array.from({ length: ROWS }, () => Array(COLS).fill('.'));

/** A brick floor with a hole in it (where the ladder comes through) and any extra gaps. */
function floorRow(g, row, holes = [], gaps = []) {
  for (let x = 0; x < COLS; x++) g[row][x] = '#';
  for (const [a, b] of gaps) for (let x = a; x <= b; x++) g[row][x] = '.';
  for (const x of holes) g[row][x] = '.';
}

/**
 * A continuous column of ladder from `top` to `bottom`. It fills the holes it passes through, but never eats
 * brick: a ladder has to be cut into the floors, not through them.
 */
function ladder(g, col, top, bottom) {
  for (let r = top; r <= bottom; r++) if (g[r][col] === '.') g[r][col] = 'H';
}

/** A rope from the ceiling down to `bottom`, again only through empty space. */
function rope(g, col, bottom) {
  for (let r = 1; r <= bottom; r++) if (g[r][col] === '.') g[r][col] = 'R';
}

function room(spec) {
  const g = blank();
  for (let x = 0; x < COLS; x++) {
    g[CEILING][x] = '#';
    g[FLOOR][x] = '#';
  }
  for (let y = 0; y < ROWS; y++) {
    g[y][0] = '#';
    g[y][COLS - 1] = '#';
  }
  for (const [row, holes, gaps] of spec.floors ?? []) floorRow(g, row, holes, gaps);
  for (const [a, y, b] of spec.brick ?? []) {
    for (let x = a; x <= b; x++) g[y][x] = '#';
  }
  for (const [a, y0, b, y1] of spec.pillar ?? []) {
    for (let y = y0; y <= y1; y++) for (let x = a; x <= b; x++) g[y][x] = '#';
  }
  for (const [x0, y, x1] of spec.crumb ?? []) for (let x = x0; x <= x1; x++) g[y][x] = 'x';
  for (const [x0, y, x1] of spec.fire ?? []) for (let x = x0; x <= x1; x++) g[y][x] = '^';
  // Nothing goes in a ladder's column: a vase or a skull there would break the ladder in two.
  const onLadder = new Set((spec.ladders ?? []).flatMap(([c, a, b]) => Array.from({ length: b - a + 1 }, (_, i) => `${c},${a + i}`)));
  for (const [c, r, ch] of spec.items ?? []) {
    if (onLadder.has(`${c},${r}`)) {
      console.warn(`  ${name}: "${ch}" at ${c},${r} is in a ladder's column, skipped`);
      continue;
    }
    g[r][c] = ch;
  }
  if (spec.at) g[spec.at[1]][spec.at[0]] = '@';
  // A ladder is cut through every floor it crosses, however that floor is built, and then fills the hole. It is
  // drawn last so nothing else can land on its column and break it.
  for (const [c, a, b] of spec.ladders ?? []) {
    for (let r = a; r <= b; r++) if (g[r][c] === '#' || g[r][c] === 'x') g[r][c] = '.';
    ladder(g, c, a, b);
  }
  for (const [c, b] of spec.ropes ?? []) rope(g, c, b);

  // The border is the last word: nothing pokes outside the room.
  for (let x = 0; x < COLS; x++) {
    g[CEILING][x] = '#';
    g[FLOOR][x] = '#';
  }
  for (let y = 0; y < ROWS; y++) {
    g[y][0] = '#';
    g[y][COLS - 1] = '#';
  }
  return g.map((r) => r.join(''));
}

/**
 * A room is two floors and three corridors. The ground is rows 7-9 (the border at row 10 is its floor), the
 * middle corridor rows 4-5 (floor at row 6) and the top corridor rows 1-2 (floor at row 3).
 *
 * `ladderGround` carries Joe from the ground up through a hole in the middle floor; `ladderTop` runs from the
 * middle corridor up through a hole in the top floor. Joe cannot climb over a brick floor, so every floor he
 * wants to get past needs one of the two.
 */
const FLOORS = (middle, top) => [
  [TOP_FLOOR, top?.holes ?? [], top?.gaps ?? []],
  [MID_FLOOR, middle?.holes ?? [], middle?.gaps ?? []],
];

const rooms = {
