private playCreature(view: Phaser.GameObjects.Sprite, kind: 'skull' | 'skeleton', face: Facing, clip?: string) {
  // A view destroyed with the scene has no anims any more; the last update before a shutdown can still reach here.
  if (!view?.scene || !view.anims) return;
  const key = clipKey(this, kind === 'skull' ? 'skull' : 'skeleton', clip ?? (kind === 'skull' ? 'bounce' : 'Walk_F'), face);
  if (key) view.play(key, true);
}

/** The guard in the entrance hall: it stands on the floor beside Joe, watching him, and never moves. */
private buildGuard() {
  if (this.defId !== START_ROOM) return;
  const e = manifest(this)?.sprites.guard;
  if (!e || !this.textures.exists(e.textureKey)) return;
  // The cell beside Joe on his floor, turned towards him.
  const row = this.spawn[1];
  const right = this.spawn[0] + 1;
  const col = this.tileAt(right, row) === WALL ? this.spawn[0] - 1 : right;
  const { x } = this.centre(col, row);
  // The sprite's own pivot is its feet, so the y is the floor line.
  const view = this.add.sprite(x, (row + 1) * TILE, e.textureKey).setDepth(55);
  const key = clipKey(this, 'guard', 'Idle_Standing', col > this.spawn[0] ? 'W' : 'E');
  if (key) view.play(key, true);
}

